export type EstadoMateria = 'aprobada' | 'cursando' | 'desaprobada' | 'disponible' | 'proxima';

export class Materia {
  private codigo: string;
  private nombre: string;
  private cargaHoraria: number;
  private correlativas: Materia[];
  private anio: number;
  private estado: EstadoMateria;

  constructor(
    codigo: string,
    nombre: string,
    cargaHoraria: number,
    correlativas: Materia[] = [],
    anio: number = 0,
    estado: EstadoMateria = 'disponible',
  ) {
    this.codigo = codigo;
    this.nombre = nombre;
    this.cargaHoraria = cargaHoraria;
    this.correlativas = correlativas;
    this.anio = anio;
    this.estado = estado;
  }

  getCodigo(): string { return this.codigo; }
  getNombre(): string { return this.nombre; }
  getCargaHoraria(): number { return this.cargaHoraria; }
  getAnio(): number { return this.anio; }
  getEstado(): EstadoMateria { return this.estado; }

  getCorrelativas(): Materia[] {
    return this.correlativas;
  }

  estaDisponible(aprobadas: Materia[]): boolean {
    const codigosAprobados = aprobadas.map(m => m.getCodigo());
    return this.correlativas.every(c => codigosAprobados.includes(c.getCodigo()));
  }
}
